
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_zpbeint_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_zpbeint", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.030867133316386e-02, -6.927946886445671e-02, -6.780239379216513e-02, -6.568454633631897e-02, -6.265235462348248e-02, -5.832235937256949e-02, -5.217518889212766e-02, -4.359028597317009e-02, -3.224247101604629e-02, -2.041287169407813e-02, -2.242145037578615e-02, -4.209292611156051e-02, -4.804673796401070e-02, -3.564558924648869e-02, -2.154996108575052e-02, -1.317771051374237e-02, -1.583831683787364e-02, -8.247091841661299e-03, -2.295605187484643e-03, -3.268687243322624e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


